<template><view class="page detail-page" v-if="item"><text class="eyebrow">案件進度 / CASE</text><text class="page-title">{{ item.title }}</text><text class="subtle">{{ item.route }} · {{ item.plateAsset ? '批文卡 '+item.plateAsset.card_number : item.vehicle?.plate || '新申請／未指定車輛' }}</text>
  <view class="status-card"><view class="row"><text class="status-caption">目前進度</text><text class="pill" :class="item.status==='已完成'?'gray':''">{{ item.status }}</text></view><text class="current-stage">{{ item.stage }}</text><text class="update-date">最近更新 {{ friendlyDate(item.updated_at) }}</text></view><button v-if="item.plateAsset" class="plate-file-link" @click="openPlate">查看關聯的兩地牌檔案 ›</button>
  <view class="row section-head"><text class="section-title">辦理項目</text><text class="count">{{ item.tasks.length }} 個節點</text></view><view class="card task-card"><view v-for="(task,index) in item.tasks" :key="task.id" class="task"><view class="step" :class="task.status==='已完成'?'done':''">{{ task.status==='已完成'?'✓':index+1 }}</view><view class="task-body"><text class="task-title">{{ task.title }}</text><text class="task-meta">{{ task.jurisdiction }} · {{ task.status }}</text></view></view></view>
  <text class="section-title">官方依據</text><view class="card source-card"><view v-for="source in selectedSources" :key="source.id" class="official-row" @click="openSource(source.url)"><view><text class="task-title">{{ source.title }}</text><text class="task-meta">{{ source.agency }} · 點擊複製官方連結</text></view><text class="official-arrow">↗</text></view><text v-if="!selectedSources.length" class="subtle">此要求須由專員先核對適用的官方指引。</text></view>
  <text class="section-title">更新紀錄</text><view class="card activity-card"><view v-for="activity in item.activities" :key="activity.id" class="activity"><view class="activity-dot"></view><view><text class="activity-text">{{ activity.detail }}</text><text class="task-meta">{{ friendlyDate(activity.created_at) }}</text></view></view></view><view class="tip">官方審批結果以實際回執及發出的牌證為準。若需補充文件，專員會與你聯絡。</view>
</view></template>
<script setup>
import { ref,computed } from 'vue'
import { onLoad,onShow } from '@dcloudio/uni-app'
import { api,friendlyDate } from '../../lib/api'
const item=ref(null),sources=ref([])
const selectedSources=computed(()=>sources.value.filter(s=>item.value?.plan?.sourceIds?.includes(s.id)))
function openSource(url){uni.setClipboardData({data:url,success:()=>uni.showToast({title:'官方連結已複製',icon:'none'})})}
function openPlate(){if(item.value?.plateAsset)uni.navigateTo({url:'/pages/plate-detail/plate-detail?id='+encodeURIComponent(item.value.plateAsset.id)})}
let requestId=''
async function load(){if(!requestId)return;try{const [record,catalog]=await Promise.all([api('/requests/'+requestId),api('/catalog')]);item.value=record;sources.value=catalog.sources}catch(e){uni.showToast({title:e.message,icon:'none'})}}
onLoad(options=>{requestId=options.id||'';load()})
onShow(()=>{if(item.value)load()})
</script>
<style scoped>
.detail-page{padding-top:29rpx}.status-card{margin-top:29rpx;background:#1b4d3e;border-radius:22rpx;color:#fff;padding:25rpx 29rpx}.status-caption{color:#c4e0cd;font-size:21rpx;font-weight:750}.current-stage{display:block;font-size:32rpx;line-height:1.35;font-weight:800;margin:18rpx 0 9rpx}.update-date{color:#b9d6c5;font-size:20rpx}.plate-file-link{margin:13rpx 0 0;background:#e5f0e7;color:#236a4d;font-size:20rpx;font-weight:800}.section-head .section-title{margin-bottom:17rpx}.count{color:#809286;font-size:20rpx}.task-card{padding:9rpx 25rpx}.task{display:flex;align-items:flex-start;gap:17rpx;padding:20rpx 0;border-bottom:1rpx solid #eaf0eb}.task:last-child{border:0}.step{display:flex;align-items:center;justify-content:center;flex:none;width:43rpx;height:43rpx;border-radius:50%;color:#5f8b70;background:#e8f3eb;font-size:21rpx;font-weight:800}.step.done{color:#fff;background:#23805d}.task-body{flex:1}.task-title{display:block;font-size:23rpx;font-weight:800;line-height:1.45}.task-meta{display:block;color:#809387;font-size:20rpx;line-height:1.5;margin-top:4rpx}.source-card{padding:9rpx 25rpx}.official-row{display:flex;align-items:center;justify-content:space-between;gap:17rpx;padding:19rpx 0;border-bottom:1rpx solid #eaf0eb}.official-row:last-child{border:0}.official-arrow{color:#348361;font-size:27rpx}.activity-card{padding:10rpx 25rpx}.activity{display:flex;gap:18rpx;padding:16rpx 0}.activity-dot{width:10rpx;height:10rpx;flex:none;border-radius:50%;background:#46a778;margin-top:12rpx}.activity-text{display:block;font-size:22rpx;line-height:1.5}.tip{color:#819487;font-size:20rpx;text-align:center;line-height:1.6;padding:18rpx 28rpx}
</style>
